      SUBROUTINE FRINGECC     CALCULATES FIRST-ORDER TRANSFER MATRIX FOR BENDING MAGNET C     FRINGING FIELDCC     LIST OF COMMON BLOCKSC      INCLUDE 'ELM2A.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM16A.CIN'      INCLUDE 'R.CIN'CC     LOCAL VARIABLESC      REAL  CB, SB2, TB1, TB2, TCORCC----------------------------------------------------------------      TB = TAN(BE)      TB2 = TB*TB      CB = COS(BE)      SB = 1.0/CB      SB2 = SB*SB      TCOR = 2.0*H0*APB(2)*LAYL      TB1 = TB - TCOR*SB*(SB2 + TB2)      R(2,1) = H0*TB      R(4,3) = - H0*TB1      LAYK = LAYKIC  500 RETURN      END